cd /workspace && node -e "
const XLSX = require('xlsx');
const fs = require('fs');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const lines = [];

for (const name of wb.SheetNames) {
  const sheet = wb.Sheets[name];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });

  lines.push('='.repeat(120));
  lines.push('Sheet: ' + name + '  (' + (rows.length - 1) + ' data rows)');
  lines.push('='.repeat(120));
  lines.push('');

  // Determine column widths
  const colWidths = [];
  for (const row of rows) {
    row.forEach((cell, i) => {
      const len = String(cell).length;
      colWidths[i] = Math.max(colWidths[i] || 0, len);
    });
  }

  // Header
  const header = rows[0];
  const headerLine = header.map((h, i) => String(h).padEnd(colWidths[i])).join('  |  ');
  lines.push(headerLine);
  lines.push(header.map((_, i) => '-'.repeat(colWidths[i])).join('--+--'));

  // Data rows
  for (let r = 1; r < rows.length; r++) {
    const row = rows[r];
    const line = header.map((_, i) => String(row[i] ?? '').padEnd(colWidths[i])).join('  |  ');
    lines.push(line);
  }
  lines.push('');
}

fs.writeFileSync('testbed/data/order_summary_extracted.txt', lines.join('\n'));
console.log('Written ' + lines.length + ' lines to testbed/data/order_summary_extracted.txt');
"
